    name = name.replace(', ', '')
    if name == flipped.replace('.', ''):
        # name was not flipped
        return False
    return rec['by_statement'].find(name) != -1


def do_flip(author):
    """
    Given an author import dict, flip its name in place
    i.e. Smith, John => John Smith

    :param dict author:
    :rtype: None
    """
    if 'personal_name' in author and author['personal_name'] != author['name']:
        # Don't flip names if name is more complex than personal_name (legacy behaviour)
        return
    first_comma = author['name'].find(', ')
    if first_comma == -1:
        return
    # e.g: Harper, John Murdoch, 1845-
    if author['name'].find(',', first_comma + 1) != -1:
        return
    if author['name'].find('i.e.') != -1:
        return
    if author['name'].find('i. e.') != -1:
        return
    name = flip_name(author['name'])
    author['name'] = name
    if 'personal_name' in author:
        author['personal_name'] = name


def pick_from_matches(author, match):
    """
    Finds the best match for author from a list of OL authors records, match.

    :param dict author: Author import representation
    :param list match: List of matching OL author records
    :rtype: dict
    :return: A single OL author record from match
    """
    maybe = []
    if 'birth_date' in author and 'death_date' in author:
        maybe = [m for m in match if 'birth_date' in m and 'death_date' in m]
    elif 'date' in author:
        maybe = [m for m in match if 'date' in m]
    if not maybe:
        maybe = match
    if len(maybe) == 1:
        return maybe[0]
    return min(maybe, key=key_int)


def _author_name_variants(name: str) -> list[str]:
    names = [name]
    if ', ' in name:
        flipped = flip_name(name)
        if flipped and flipped != name:
            names.append(flipped)
    return names


def _author_years_match(author: dict[str, Any], candidate: "Author") -> bool:
    return all(
        extract_year(author.get(field) or '')
        == extract_year(candidate.get(field) or '')
        for field in ('birth_date', 'death_date')
    )


def find_author(author: dict[str, Any]) -> list["Author"]:
    """
    Searches OL for an author by name.

    :param str name: Author's name
    :rtype: list
    :return: A list of OL author representations than match name
    """

    names = _author_name_variants(author['name'])
    queries = []
    for field in ('name', 'alternate_names'):
        for name in names:
            # Infogami expands * in a ~ query. Equality keeps a name's * literal.
            query_field = field if '*' in name else f'{field}~'
            queries.append({'type': '/type/author', query_field: name})

    birth_year = extract_year(author.get('birth_date') or '')
    death_year = extract_year(author.get('death_date') or '')
    if birth_year and death_year and (tokens := names[-1].split()):
        surname = tokens[-1]
        query = {
            'type': '/type/author',
            'birth_date~': f"*{birth_year or '-1'}*",
            'death_date~': f"*{death_year or '-1'}*",
        }
        if '*' not in surname:
            query['name~'] = f'* {surname}'
        queries.append(query)

    authors = []
    seen = set()
    for query in queries:
        for key in web.ctx.site.things(query):
            obj = web.ctx.site.get(key)
            redirects = {key}
            while obj.type.key == '/type/redirect':
                location = obj['location']
                assert location not in redirects
                redirects.add(location)
                obj = web.ctx.site.get(location)
            if obj['key'] not in seen:
                seen.add(obj['key'])
                authors.append(obj)
    return authors


def find_entity(author: dict[str, Any]) -> "Author | None":
    """
    Looks for an existing Author record in OL by name
    and returns it if found.

    :param dict author: Author import dict {"name": "Some One"}
    :return: Existing Author record if found, or None.
    """
    names = _author_name_variants(author['name'])
    folded_names = {name.casefold() for name in names}
    things = find_author(author)
    matching_years = [a for a in things if _author_years_match(author, a)]
    for a in matching_years:
        assert a.type.key == '/type/author'

    exact = [a for a in matching_years if a.get('name', '').casefold() in folded_names]
    if exact:
        return pick_from_matches(author, exact)

    alternate = [
        a
        for a in matching_years
        if any(name.casefold() in folded_names for name in a.get('alternate_names', []))
    ]
    if alternate:
        return pick_from_matches(author, alternate)

    birth_year = extract_year(author.get('birth_date') or '')
    death_year = extract_year(author.get('death_date') or '')
    if birth_year and death_year and (tokens := names[-1].split()):
        surname = tokens[-1].casefold()
        surname_matches = [
            a
            for a in matching_years
            if a.get('name', '').split()
            and a['name'].split()[-1].casefold() == surname
        ]
        if surname_matches:
            return pick_from_matches(author, surname_matches)
    return None


def remove_author_honorifics(name: str) -> str:
    """Remove a leading honorific while preserving names made only of one."""
    comparison_name = re.sub(r'[\W_]+', '', name.casefold())
    if comparison_name in {
        re.sub(r'[\W_]+', '', exception) for exception in HONORIFC_NAME_EXECPTIONS
    }:
        return name

    folded_name = name.casefold()
    for honorific in HONORIFICS:
        if not folded_name.startswith(honorific):
            continue
        remainder = name[len(honorific) :]
        if remainder and not (remainder[0].isspace() or remainder[0] in '.,:'):
            continue
        if stripped := remainder.lstrip(' \t\r\n.,:'):
            return stripped
    return name


def import_author(author: dict[str, Any], eastern=False) -> "Author | dict[str, Any]":
    """
    Converts an import style new-author dictionary into an
    Open Library existing author, or new author candidate, representation.
    Does NOT create new authors.

    :param dict author: Author import record {"name": "Some One"}
    :param bool eastern: Eastern name order
    :return: Open Library style Author representation, either existing with "key",
             or new candidate without "key".
    """
    if existing := find_entity(author):
        assert existing.type.key == '/type/author'
        for k in 'last_modified', 'id', 'revision', 'created':
            if existing.k:
                del existing.k
        new = existing
        if 'death_date' in author and 'death_date' not in existing:
            new['death_date'] = author['death_date']
        return new
    if author.get('entity_type') != 'org' and not eastern and '*' not in author['name']:
        do_flip(author)
    a = {'type': {'key': '/type/author'}, **author}
    return a


